// Generated by `just generate` from `src/plugins/claudetto/slices/turngate/domain/jobs.ts`. Edit the source and run `just generate`.
// The job part of the turn gate: a `Bash` command that starts a process that Claude Code does not track, or that stops processes by a pattern.
// The check reads the parse of the shell reader, so it is on structure and not on words of a reply.
// A job that `run_in_background` starts is a background task, which the stop gate sees in `background_tasks`.
// A job of a lone `&` with no `wait`, or of `nohup`, `setsid`, or `disown`, outlives the call, and no stop gate sees it.

import { type ParseResult, parse } from "../../../kernel/shell.ts";
import { baseName, stripWrappers } from "../../../kernel/wrappers.ts";
import { JOBS_REASON, JOBS_STOP } from "../prompts.ts";

/** The commands that detach a process from the shell of the call. */
const DETACH = new Set(["nohup", "setsid", "disown"]);

/** The commands that stop each process that matches a pattern. */
const BY_PATTERN = new Set(["pkill", "killall"]);

/** The base names of the wrapper words of `argv`, and the base name of its command. */
const heads = (argv: string[]): { wrappers: string[]; command: string } => {
  const core = stripWrappers(argv);
  return {
    wrappers: argv.slice(0, argv.length - core.length).map(baseName),
    command: baseName(core[0] ?? ""),
  };
};

/** The faults of a parsed command, each as a short name for the reason. */
export const jobFaults = (parsed: ParseResult): string[] => {
  const all = parsed.commands.map(heads);
  const names = new Set(all.map((h) => h.command));
  const faults: string[] = [];
  if (parsed.background.length > 0 && !names.has("wait"))
    faults.push("a job of a lone `&` with no `wait`");
  if (
    all.some(
      (h) => DETACH.has(h.command) || h.wrappers.some((w) => DETACH.has(w)),
    )
  )
    faults.push("a job of `nohup`, `setsid`, or `disown`");
  if (
    [...names].some((n) => BY_PATTERN.has(n)) ||
    (names.has("kill") && names.has("pgrep"))
  )
    faults.push("a stop of processes by a pattern");
  return faults;
};

/** The faults of `command`, a raw `Bash` input. */
export const commandFaults = (command: unknown): string[] =>
  jobFaults(parse(command));

/**
 * The deny reason for the faults of a command.
 * It names `TaskStop` only when the session has that tool, because a settings rule can deny it (D32).
 */
export const jobsReason = (
  faults: readonly string[],
  hasTaskStop: boolean,
): string =>
  JOBS_REASON({
    faults: faults.map((f) => `- ${f}`).join("\n"),
    stop: hasTaskStop ? ` ${JOBS_STOP}` : "",
  });
